const PORTION = 10; // Kanäle je Portion (talents_plattform_abruf_liste p_anzahl)
// Lauf starten (Stefan 18.10.2026): Portionen der fälligen Kanäle nacheinander abarbeiten (talents_abruf_liste mit p_anzahl).
// erledigt = in diesem Lauf schon bearbeitete Kanäle (auch mit Fehler), damit sie nicht erneut drankommen.
// Sofortabruf (Stefan 19.10.2026): Aufruf aus ALLY 16 über "Sofort (Einladung)" mit kanal_id und erstabruf -> nur dieser Kanal
// (Liste mit Kanal-Filter, Migration 52; erstabruf = bis 30 Tage zurück). Der nächtliche Lauf bleibt unverändert.
const sofort = $('Sofort (Einladung)').isExecuted ? ($('Sofort (Einladung)').first().json || {}) : null;
if (sofort) {
  const kanal_id = Number(sofort.kanal_id);
  if (!(Number.isInteger(kanal_id) && kanal_id > 0)) return [];
  // Migration 194 (Stefan 01.11.2026, „Daten jetzt abrufen“): alle_beitraege nur vom Knopf im Talent-Profil (ALLY 20); ALLY 16 schickt es nicht (= false)
  return [{ json: { runde: 0, erledigt: [], anzahl: PORTION, kanal_id, erstabruf: sofort.erstabruf === true, alle_beitraege: sofort.alle_beitraege === true } }];
}
