return [{ json: { runde, erledigt, anzahl: PORTION } }];

const PL = 'threads';
// Zugang auswerten (Stefan 18.10.2026, Vertrag Migration 48, 3.3): Antwort der Erneuerung (Google/Pinterest/TikTok: refresh_token,
// Threads: th_refresh_token) einordnen, OHNE Schlüssel auszugeben. Neue Schlüssel liest "Zugang speichern" direkt aus "Zugang erneuern",
// den Zugriffsschlüssel für die Abrufe liest "Plattform-Abruf" ebenfalls dort (nur, wenn kanal_id und zugang_ok hier passen).
// PL setzt der Bau vor diesen Code.
const NAME = { youtube: 'Google', pinterest: 'Pinterest', tiktok: 'TikTok', threads: 'Threads' }[PL] || PL;
const MUSTER = /(ya29\.|1\/\/0|act\.|rft\.|pina_|pinr|EAA|TH[A-Z]{2})[A-Za-z0-9!*._|-]{10,}/g;
const kurz = (t, n) => String(t == null ? '' : t).replace(MUSTER, '***').replace(/(access_token|refresh_token|client_secret)=[^&\s"']+/gi, '$1=***')
  .replace(/\s+/g, ' ').trim().slice(0, n || 160);
const zahl = v => (typeof v === 'number' && isFinite(v)) ? v : (typeof v === 'string' && /^[0-9]{1,12}$/.test(v.trim()) ? Number(v.trim()) : null);
const start = ($('Zugang erneuern?').first(0) || {}).json || {};
const a = $input.first().json || {};
const status = Number(a.statusCode) || 0;
let b = a.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = null; } }
b = b && typeof b === 'object' ? b : {};
const tok = typeof b.access_token === 'string' && b.access_token.length >= 10 && !/\s/.test(b.access_token);
let fehler = null, gueltig_bis = null, neuer_schluessel = false, berechtigungen = null;
// Fehler: Google/TikTok error + error_description; Meta (Threads) error-Objekt mit code; Pinterest code + message (Format nicht geprüft)
const eo = b.error && typeof b.error === 'object' ? b.error : null;
const code = eo ? String(eo.code || eo.type || 'fehler') : (typeof b.error === 'string' ? b.error : (b.code !== undefined ? String(b.code) : ''));
const text = eo ? (eo.message || '') : (b.error_description || b.message || '');
const VOR = 'Erneuerung des Zugangs bei ' + NAME + ' fehlgeschlagen. ';
if (!status) {
  fehler = { code: 'netz', text: VOR + NAME + ' war nicht erreichbar.', abgelaufen: false };
} else if (status !== 200 || !tok) {
  // abgelaufen: invalid_grant (Google laut Doku: abgelaufen oder entzogen; TikTok gleiches OAuth-Muster, nicht geprüft), Meta-Code 190 (Threads)
  const abgelaufen = /^invalid_grant$/.test(code) || (PL === 'threads' && code === '190');
  fehler = { code: (code || ('http' + status)).slice(0, 40), text: VOR + (text ? NAME + ' meldet: ' + kurz(text) : 'HTTP ' + status + '.')
    + (abgelaufen ? ' Das Talent muss den Kanal neu verbinden.' : ''), abgelaufen };
} else {
  if (PL === 'threads') {
    neuer_schluessel = true;  // th_refresh_token liefert einen neuen langlebigen Schlüssel (60 Tage)
    gueltig_bis = zahl(b.expires_in) > 0 ? zahl(b.expires_in) : 5184000;
  } else {
    neuer_schluessel = typeof b.refresh_token === 'string' && b.refresh_token.length >= 10 && !/\s/.test(b.refresh_token);
    const rb = PL === 'pinterest' ? zahl(b.refresh_token_expires_in) : (PL === 'tiktok' ? zahl(b.refresh_expires_in) : zahl(b.refresh_token_expires_in));
    gueltig_bis = rb > 0 ? rb : null;
    const sc = typeof b.scope === 'string' ? b.scope.split(/[\s,]+/).filter(x => /^[A-Za-z0-9_.:\/-]{1,120}$/.test(x)) : [];
    berechtigungen = sc.length ? sc : null;
  }
}
return [{ json: { kanal_id: start.kanal_id, start: Object.assign({}, start, { zugang: { ok: !fehler, fehler } }), zugang_ok: !fehler, zugang_fehler: fehler, neuer_schluessel, gueltig_bis, berechtigungen } }];

// ---- Fehler der Meta-APIs (Facebook-Seiten, Threads) (Stefan 18.10.2026) ----
// Fehlerobjekt error {code, message, error_subcode}; 190 = Schlüssel ungültig, 10/200–299 Rechte, 4/17/32/613/80000–80099 Grenzen
// (Rate Limiting: https://developers.facebook.com/docs/graph-api/overview/rate-limiting), 1/2/5xx vorübergehend.
const ABGELAUFEN_BEI_TOKEN = true;
function fehlerPlattform(r) {
  const status = Number(r.statusCode);
  const b = r.body && typeof r.body === 'object' ? r.body : null;
  const e = b && b.error && typeof b.error === 'object' ? b.error : null;
  if (!e && status >= 200 && status < 300 && b) return null;
  if (!e && !status) return { code: 'netz', roh: '', text: NAME + ' war nicht erreichbar.', klasse: 'temporaer' };
  if (!e) return { code: 'http' + (status || ''), roh: '', text: 'Unerwartete Antwort von ' + NAME + ' (HTTP ' + (status || '?') + ').', klasse: status === 429 ? 'grenze' : (status >= 500 ? 'temporaer' : 'sonst') };
  const code = Number(e.code);
  const roh = String(e.message || e.error_user_msg || e.type || '');
  let klasse = 'sonst';
  if (code === 190 || code === 102) klasse = 'token';
  else if (code === 10 || code === 3 || (code >= 200 && code <= 299)) klasse = 'rechte';
  else if ([4, 17, 32, 613].indexOf(code) >= 0 || (code >= 80000 && code <= 80099) || status === 429) klasse = 'grenze';
  else if (code === 1 || code === 2 || status >= 500) klasse = 'temporaer';
  return { code: isFinite(code) ? String(code) : 'graph', roh, text: NAME + ' meldet: ' + kurz(roh, 180), klasse, stopp_alle: code === 4 };
}
function kennzahl(m) {
  if (!m || typeof m !== 'object') return null;
  if (m.total_value && zahl(m.total_value.value) !== null) return zahl(m.total_value.value);
  if (Array.isArray(m.values) && m.values.length) {
    let s = null;
    for (const v of m.values) if (v && zahl(v.value) !== null) s = (s || 0) + zahl(v.value);
    return s;
  }
  return null;
}

// ---- Plattform-Modul Threads (Stefan 18.10.2026, Vertrag Migration 48, 1.2) ----
// graph.threads.net/v1.0; Profil GET /me?fields=id,username; Konto je Tag: /{id}/threads_insights?metric=views,likes,replies,reposts,quotes,clicks
// &since&until (Unix); followers_count und follower_demographics ohne since/until (https://developers.facebook.com/documentation/threads/insights.md);
// Beiträge GET /{id}/threads (fields, since, limit); je Beitrag /{media-id}/insights?metric=views,likes,replies,reposts,quotes,shares.
// views des Kontos = Profilaufrufe (gespeichert als profile_views, nicht als Aufrufe); replies als comments (Antworten auf Beiträge).
const PL = 'threads', NAME = 'Threads';
const MAX_SEITEN = 4;
const KONTO_M = { views: 'profile_views', likes: 'likes', replies: 'comments', reposts: 'reposts', quotes: 'quotes', clicks: 'clicks' };
const BEITRAG_M = { views: 'views', likes: 'likes', replies: 'comments', reposts: 'reposts', quotes: 'quotes', shares: 'shares' };
function beitragInsights(st, id) {
  st.offen.push({ art: 'beitrag', extern_id: id, pfad: id + '/insights', query: { metric: Object.keys(BEITRAG_M).join(',') } });
}
function beginnen(st, k) {
  const u = st.extern_id;
  st.offen.push({ art: 'konto', pfad: 'me', query: { fields: 'id,username' } });
  st.offen.push({ art: 'follower', pfad: u + '/threads_insights', query: { metric: 'followers_count' } });
  for (const t of st.tage) st.offen.push({ art: 'tag', tag: t.tag, pfad: u + '/threads_insights',
    query: { metric: Object.keys(KONTO_M).join(','), since: t.since, until: t.until } });
  st.offen.push({ art: 'beitraege', seite: 1, pfad: u + '/threads',
    query: { fields: 'id,media_product_type,media_type,permalink,text,timestamp,thumbnail_url,media_url', limit: 25, since: st.seit_unix || undefined } });
  for (const id of st.verfolgt) beitragInsights(st, id);
  if (st.zielgruppe_faellig) {
    st.zg_angefragt = true;
    for (const a of ['age', 'gender', 'country', 'city']) {
      st.zg_offen++;
      st.offen.push({ art: 'zielgruppe', zg: true, aufteilung: a, pfad: u + '/threads_insights', query: { metric: 'follower_demographics', breakdown: a } });
    }
  }
}
function wertAus(m) {
  if (!m) return null;
  if (Array.isArray(m.link_total_values)) { let s = null; for (const x of m.link_total_values) if (x && zahl(x.value) !== null) s = (s || 0) + zahl(x.value); return s; }
  return kennzahl(m);
}
function erfolg(st, req, body) {
  const data = Array.isArray(body.data) ? body.data : [];
  if (req.art === 'konto') {
    if (String(body.id || '') && String(body.id) !== String(st.extern_id)) { st.abbruch = { code: 'konto', text: 'Threads meldet ein anderes Profil als gespeichert. Bitte den Kanal neu verbinden.', abgelaufen: false, pause: 0 }; return; }
    if (typeof body.username === 'string' && body.username.trim()) st.d.konto_name = body.username.trim();
  } else if (req.art === 'follower') {
    const m = data.find(x => x && x.name === 'followers_count');
    kontoWert(st, 'followers_count', wertAus(m));
  } else if (req.art === 'tag') {
    for (const m of data) if (m && KONTO_M[m.name]) tagWert(st, req.tag, KONTO_M[m.name], wertAus(m));
  } else if (req.art === 'beitraege') {
    let aelter = false;
    for (const p of data) {
