      const t = Date.parse(p.timestamp);
      if (st.seit_unix && isFinite(t) && t / 1000 < st.seit_unix) { aelter = true; continue; }
      const neu = !st.d.beitraege[p.id] && !verfolgt(st, p.id);
      beitragSetzen(st, { extern_id: p.id, art: p.media_type, produkt_art: p.media_product_type, erstellt: isFinite(t) ? new Date(t).toISOString() : undefined,
        link: p.permalink, vorschau_url: p.thumbnail_url || (p.media_type === 'IMAGE' ? p.media_url : undefined), text_inhalt: p.text });
      if (neu) beitragInsights(st, p.id);
    }
    const next = body.paging && body.paging.next ? weiterParameter(body.paging.next) : null;
    if (next && !aelter && st.seit_unix && req.seite < MAX_SEITEN) st.offen.push({ art: 'beitraege', seite: req.seite + 1, pfad: req.pfad, query: Object.assign({}, req.query, next) });
  } else if (req.art === 'beitrag') {
    const w = {};
    for (const m of data) if (m && BEITRAG_M[m.name] && wertAus(m) !== null) w[BEITRAG_M[m.name]] = wertAus(m);
    if (Object.keys(w).length) beitragSetzen(st, { extern_id: req.extern_id, werte: w });
  } else if (req.art === 'zielgruppe') {
    // Antwortform für follower_demographics zeigt die Doku nicht; gelesen wird total_value.breakdowns[].results[] (wie Instagram) – nicht geprüft
    const m = data.find(x => x && x.name === 'follower_demographics');
    const w = {};
    const bd = m && m.total_value && Array.isArray(m.total_value.breakdowns) ? m.total_value.breakdowns : [];
    for (const b of bd) for (const r of (Array.isArray(b.results) ? b.results : [])) {
      const key = Array.isArray(r.dimension_values) ? r.dimension_values.join(' ') : null;
      if (key && zahl(r.value) !== null) w[key] = zahl(r.value);
    }
    zielgruppe(st, req.aufteilung, 'follower_demographics', w);
  }
}
// Zielgruppe (unter 100 Followern) und Beitrags-Insights einzelner Beiträge: überspringen; übrige Fehler brechen ab
function sonstFehler(st, req, f) {
  if (req.art === 'zielgruppe' && f.klasse !== 'token') return true;
  if (req.art === 'beitrag' && f.klasse === 'sonst') return true;
  return false;
}

// ---- Gemeinsamer Teil "Abruf steuern" für Facebook, Threads, YouTube, Pinterest, TikTok (Stefan 18.10.2026, Vertrag Migration 48, 3.4) ----
// Muster wie TALENTS 1: eine Anfrage-Warteschlange je Kanal; der Zustand st reist im ersten Eintrag mit.
// Eingang A: Startzeile (start === true aus "Je Kanal" bzw. "Zugang erneuern?", oder Feld start aus "Zugang speichern").
// Eingang B: Antworten von "Plattform-Abruf" (gleiche Reihenfolge wie "Anfrage").
// Ausgabe: aktion 'abruf' (url, methode, body_text) oder aktion 'ende' (daten zum Speichern, fehler).
