const BUENDEL = 10;
const MAX_ABRUFE = 1500;
const MUSTER = /(ya29\.|1\/\/0|act\.|rft\.|pina_|pinr|EAA|IGAA|IGQV|TH[A-Z]{2})[A-Za-z0-9!*._|-]{16,}/g;

function kopie(x) { return JSON.parse(JSON.stringify(x)); }
function zahl(v) {
  if (typeof v === 'number' && isFinite(v)) return v;
  if (typeof v === 'string' && /^-?[0-9]{1,15}(\.[0-9]{1,6})?$/.test(v.trim())) return Number(v.trim());
