  return String(t == null ? '' : t).replace(MUSTER, '***').replace(/(access_token|refresh_token|client_secret|client_key)=[^&\s"']+/gi, '$1=***')
    .replace(/\s+/g, ' ').trim().slice(0, n || 200);
