function httpsAdresse(u) {
  if (typeof u !== 'string' || !/^https:\/\/\S+$/.test(u) || u.length > 2000) return undefined;
  if (/access_token|refresh_token|client_secret|client_key/i.test(u) || /(ya29\.|EAA|act\.|pina_)[A-Za-z0-9_-]{20,}/.test(u)) return undefined;
  return u;
}
function enc(v) { return encodeURIComponent(String(v)); }
